W += [
E('dispute','/dɪˈspjuːt/；名词也读 /ˈdɪspjuːt/','争议、纠纷；争论；质疑、否认','有人摆出一个说法，另一方说“我不接受，需要重新讨论”，就出现了 dispute。','拉丁 dis- 分开 + putare 考察 → disputare，经过古法语 desputer 或直接拉丁来源进入英语；英语名词沿动词发展。',DISPUTE,'名词可以是账单、边界、合同等方面的分歧。动词 dispute a claim 是质疑该说法，不是必须大声吵架；in dispute 表示尚有争议。','a dispute over payment；settle a dispute；dispute a claim；be in dispute。','discussion 是讨论；dispute 带不同意见或挑战。deny 直接否认，dispute 可以要求证据、提出异议。',('They settled the dispute over the final payment.','他们解决了尾款方面的纠纷。'),('Several researchers dispute that conclusion.','几位研究者对这个结论提出异议。'),sources=[S('dispute'),M('dispute')]),
E('disputed','/dɪˈspjuːtɪd/','有争议的；被质疑的；争夺中的','同一件事有几方给出不同答案，归属或真伪还没有得到共同承认。','dispute + -ed；/t/ 后 -ed 读 /ɪd/，可作过去分词或形容词。',A(DISPUTE,'英语 dispute + -ed → disputed','受到争论、质疑或争夺的'),'a disputed claim 说有人反对，不等于已经证明说法为假；disputed territory 说领土归属有争议，词本身不替任何一方作结论。','a disputed claim；a disputed interpretation；disputed territory。','disputable 说可以质疑、有可争论之处；disputed 说实际已经受到质疑。',('The disputed figure was removed from the summary pending verification.','那个有争议的数字被暂时从摘要中移除，等待核实。'),('The two historians offered different readings of the disputed passage.','两位历史学家对有争议的段落作出了不同解读。'),sources=[K('disputed'),S('dispute')]),
E('disputable','/dɪˈspjuːtəbəl/','可争议的；值得质疑的','这条推理中还有地方可以提出问题，不能直接宣布“已经没有讨论余地”。','接法语 disputable 或拉丁 disputabilis，后者来自 disputare + -abilis；今天可拆成 dispute + -able 理解，但历史包括整个形容词的借入。',DISPUTABLE,'常修饰 claim、assumption、conclusion。它表示有可争论之处，并不要求现场已经有人开口反对。','a disputable claim；a disputable assumption；highly disputable。','disputed 是已经被争论；disputable 是能够或值得被争论。',('The argument rests on a disputable assumption.','这个论证建立在一个有待商榷的假设上。'),('Whether that was the best choice remains disputable.','那是否是最佳选择，仍有讨论余地。'),sources=[S('disputable'),M('disputable')]),
E('disputation','英 /ˌdɪspjuˈteɪʃən/；美 /ˌdɪspjəˈteɪʃən/','争辩；正式辩论','把一个命题摆到台前，一方提出理由，另一方反驳，再逐条回答；比随口争吵更像有章法的交锋。','拉丁 disputatio 经古法语 desputasion 或直接借入英语；现代可对应 dispute + -ation，但名词有自己的法语、拉丁借入路线。',DISPUTATION,'尤其常见于哲学、神学和大学史，指围绕命题进行的正式辩论；也可泛指争论。它并不要求双方最后达成一致。','a public disputation；a theological disputation；engage in disputation。','dispute 是更普通的分歧或争议；disputation 更正式，常带论辩过程或学术传统。',('The students prepared arguments for a public disputation.','学生们为一场公开辩论准备论据。'),('The chapter describes the role of disputation in medieval teaching.','这一章描述了论辩在中世纪教学中的作用。'),sources=[S('disputation'),M('disputation'),'https://www.oxfordlearnersdictionaries.com/definition/english/disputation']),
E('indisputable','/ˌɪndɪˈspjuːtəbəl/','无可争辩的；不容置疑的','证据已经把关键事实钉牢，说话者认为再否认也没有合理依据。','来自晚期拉丁 indisputabilis：in- 不 + disputabilis 可争论的。现代能拆成 in- + disputable，但不能省掉整词拉丁来源。',INDISPUTABLE,'这是很强的判断。indisputable evidence、an indisputable fact 都表示说话者认定证据充分；词语本身并不能替代实际举证。','indisputable evidence；an indisputable fact；indisputable proof。','undisputed 只说没有人提出争议；indisputable 进一步说没有合理争辩空间。',('The dated photograph provides indisputable evidence that the building already existed.','这张注明日期的照片确凿地证明，当时这栋建筑已经存在。'),('The arithmetic error is indisputable.','这个算术错误无可争辩。'),sources=[S('indisputable'),M('indisputable')]),
E('indisputably','/ˌɪndɪˈspjuːtəbli/','无可争辩地；毫无疑问地','在整个判断前面加一层强肯定：“这一点没有合理的争议空间。”','indisputable 的 -able 变为 -ably；英语副词派生，底层沿拉丁 indisputabilis。',A(INDISPUTABLE,'英语 indisputable → indisputably','以无可争辩的方式；毫无疑问地'),'常放在形容词前或 be 后，如 indisputably important。它表示说话者的强确信，不是一个表示概率百分比的统计词。','indisputably true；indisputably important；indisputably the largest。','arguably 表示可以提出理由这样认为；indisputably 的断言力度更强。',('The new bridge is indisputably longer than the old one.','新桥毫无疑问比旧桥更长。'),('Her work is indisputably important to the history of the field.','她的工作对这个领域的发展史无疑非常重要。'),sources=[M('indisputable'),K('indisputably')]),
E('undisputed','/ˌʌndɪˈspjuːtɪd/','无争议的；未受挑战的；公认的','桌上这项事实，目前各方都接受；或者一个头衔没有其他竞争者提出有效挑战。','un- 不 + disputed 被争论的，英语否定派生。un- 在这里不来自拉丁 unus“一”，而是英语否定前缀。',A(A(DISPUTE,'英语 disputed','被争论的'),'英语 un- + disputed → undisputed','没有受到争议的'),'常见 undisputed fact、undisputed leader、undisputed champion。它说争议状态或公认地位，不保证所有未来讨论都不可能出现。','an undisputed fact；the undisputed leader；an undisputed title。','indisputable 声称无可反驳；undisputed 描述尚未或没有被反驳。',('The date of the meeting is undisputed, but its purpose is debated.','会议日期没有争议，但会议目的仍有争论。'),('She became the undisputed leader of the team.','她成了团队公认的领袖。'),sources=[S('undisputed'),K('undisputed')]),
E('reputation','英 /ˌrepjuˈteɪʃən/；美 /ˌrepjəˈteɪʃən/','名声；口碑；声誉','你还没进房间，别人已经听说“这个人做事可靠”或“这家店爱拖延”：这份在人们心里累积的看法就是 reputation。','来自法语 reputation／reputacion 或直接拉丁 reputatio；reputare 是考虑、评价，re- 在此常解释为反复。名词是独立借入，不是英语 repute 加后缀这一条路线就能概括。',REPUTATION,'可以好也可以坏：a reputation for honesty 是诚实名声，a reputation for being late 是爱迟到的名声。单独说 protect your reputation 常偏向维护好声誉。','a reputation for quality；build a reputation；damage a reputation。','fame 主要说有多出名；reputation 说人们怎样评价。很有名也可能口碑差。',('The café has a reputation for friendly service.','这家咖啡馆以服务友好而有口碑。'),('Repeated delays damaged the company’s reputation.','一再延误损害了公司的声誉。'),sources=[S('reputation'),M('reputation')]),
E('reputational','英 /ˌrepjuˈteɪʃənəl/；美 /ˌrepjəˈteɪʃənəl/','声誉方面的；影响口碑的','损失不只在账本里，也可能是别人以后不再信任你；reputational 把关注点转到这份公众评价。','reputation + -al，是英语形容词派生；不表示“反复计算的”。',A(REPUTATION,'英语 reputation + -al → reputational','与声誉有关的'),'reputational damage 是声誉受损，reputational risk 是可能影响外界评价的风险；不是说这个机构本来就有好名声。','reputational damage；reputational risk；reputational consequences。','reputable 是口碑好的；reputational 只是与口碑有关，好坏都可能。',('The false statement caused serious reputational damage.','那份不实声明严重损害了声誉。'),('The team considered the reputational consequences of the decision.','团队考虑了这一决定对声誉的影响。'),sources=[K('reputational'),M('reputational')]),
E('repute','/rɪˈpjuːt/','名声、声望；认为、看作','把人们对某人的评价收成一个简洁的名词：of good repute 就是大家说起来都认可。','动词经古法语 reputer 或直接拉丁 reputare 传入，名词 repute 后由英语动词发展；与独立借入的 reputation 同源。',REPUT,'现代名词常在固定搭配中出现，如 a scholar of international repute。动词较少单独用原形，更多见被动 be reputed to be。','of good repute；of international repute；held in high repute；be reputed to be。','reputation 更日常；repute 较正式。high repute 明确是好声望，不能把所有 repute 都当作赞美。',('She is a scholar of international repute.','她是一位享有国际声望的学者。'),('The institution was once held in high repute.','这家机构曾受到高度尊重。'),sources=[S('repute'),M('repute')]),
E('reputed','/rɪˈpjuːtɪd/','据说的；一般认为的；有声望的','信息来自“人们是这样说的”，说话者不一定已经亲自证实。','repute + -ed；先有被评价、被认为的分词形容词，随后发展出“据说是”的常用法。',A(REPUT,'英语 repute + -ed → reputed','被认为的；据说的'),'be reputed to be 常接一种身份、能力或特征。reputed 也有“有名望的”用法，但在 a reputed owner 等结构中不能自动读成赞扬。','be reputed to be；a reputed expert；the reputed author。','reputable 通常明确口碑好；reputed 强调被人这样称说，甚至可能带保留。',('The house is reputed to be the oldest in the village.','据说这栋房子是村里最古老的。'),('The reputed author of the letter denied writing it.','那位被认为是写信人的人否认自己写过这封信。'),sources=[S('reputed'),M('reputed')]),
E('reputedly','/rɪˈpjuːtɪdli/','据说；相传；按一般说法','给整句话加一个来源提示：“这是传闻或公众说法，不是我在这里亲自证明的。”','reputed + -ly；英语副词，沿 repute“认为”的词义发展。',A(A(REPUT,'英语 reputed','据说的、被认为的'),'英语 reputed + -ly → reputedly','据说、相传'),'可以修饰整个断言，如 reputedly built in...。它通常保留一定距离，但并不意味着说话者断定传闻是假的。','reputedly built；reputedly the oldest；reputedly worth。','reportedly 更明确指报道或报告所述；reputedly 可以来自一般名声或传说。',('The garden was reputedly designed by a visiting architect.','据说这座花园由一位到访的建筑师设计。'),('He reputedly solved the puzzle in a few minutes.','据说他几分钟就解开了谜题。'),sources=[K('reputedly'),M('reputedly')]),
E('reputable','美 /ˈrepjətəbəl/','声誉好的；值得信赖的','当你把这家店的名字说出来，别人通常会说“它做事靠得住”：这就是 reputable 的正面判断。','repute 名词 + -able，英语派生。早期有“可纳入考虑”的意思，后来稳定为享有好评价，不能照字面只译成“能被认为的”。',REPUTABLE,'常修饰商家、出版机构、来源和专业人员。强调长期口碑和可信度，不等于名气最大或从不犯错。','a reputable company；a reputable source；a reputable publisher。','reputed 是据说如此；reputable 是口碑好。famous 只说出名，不保证可信。',('The article cites several reputable sources.','文章引用了几家可信的来源。'),('She bought the instrument from a reputable dealer.','她从一家口碑良好的商家购买了乐器。'),sources=[S('reputable'),M('reputable')]),
E('disreputable','美 /ˌdɪsˈrepjətəbəl/','名声不好的；不体面的；可疑的','别人听到这个名字就皱眉，或从它的做派觉得靠不住；这个词把好的口碑翻到了反面。','dis- 否定、相反 + reputable，英语构词；不是从英语 dispute 派生。',A(REPUTABLE,'英语 dis- + reputable → disreputable','名声不好、行为不体面的'),'可以说不可靠的生意、声名狼藉的人，也可用带幽默色彩的方式形容破旧、不体面的外观。它不自动等于已经被法院认定违法。','a disreputable dealer；disreputable behaviour；a disreputable appearance。','unpopular 是不受欢迎；disreputable 更关乎不良名声、品行或可信度。',('The investigation exposed a disreputable business practice.','调查揭露了一种不光彩的经营手法。'),('He arrived wearing a rather disreputable old coat.','他穿着一件颇不体面的旧外套来了。'),sources=[S('disreputable'),M('disreputable')]),
E('disrepute','/ˌdɪsrɪˈpjuːt/','坏名声；声誉扫地的状态','不是一次别人不喜欢你，而是公众评价已经落到低处，信任被损坏了。','dis- 不良、相反 + repute 名声，英语抽象名词。',A(REPUT,'英语 dis- + repute → disrepute','不良名声、低评价'),'最常见 bring something into disrepute，让某机构或职业蒙羞；fall into disrepute 是逐渐失去声誉。通常不可数。','bring into disrepute；fall into disrepute；be held in disrepute。','disreputable 是形容词，用来修饰人或事；disrepute 是名词，表示名誉受损的状态。',('The scandal brought the profession into disrepute.','丑闻让整个职业的名誉受损。'),('The theory fell into disrepute after repeated failures.','多次失败后，这套理论失去了信誉。'),sources=[S('disrepute'),M('disrepute')]),
E('putative','/ˈpjuːtətɪv/','推定的；一般认为的；尚待证实的','先给一个可能的身份贴上暂定标签：眼下看起来像，但证据还不足以完全坐实。','晚期拉丁 putativus 接 putatus“被认为的”，来自 putare 判断；经中古法语 putatif 或直接拉丁来源进入英语。',PUTATIVE,'常见 putative author、putative cause、putative function。科研中 putative function 可以是根据线索推测的功能，不等于已经通过实验确认。','a putative cause；a putative author；a putative function。','potential 说可能将来成为或发生；putative 通常说现在被认为具有某种身份或作用，两者不应随便替换。',('The paper identifies a putative cause but does not establish it conclusively.','论文提出了一个推定原因，但没有作出确证。'),('The putative author of the poem lived in the same region.','这首诗被推定的作者生活在同一地区。'),sources=[S('putative'),K('putative')]),
]
W += [
E('impute','/ɪmˈpjuːt/','归因于；归责于；统计中插补缺失值','像在一份账上把某项记到某人名下：说“这次失误算他的”，就是把责任归过去。','拉丁 in- 向里，在 p 前同化为 im-，加 putare 计算、考虑，形成 imputare；经法语 imputer 或直接拉丁来源借入英语。这里 im- 不是“不”。',IMPUTE,'impute a motive to someone 是认定对方有某种动机，常带负面评价；并非一定是客观事实。统计用法则是按方法给缺失或不合用的数据补上替代值，并明确这些值不是原始观测。','impute blame to；impute a motive to；impute missing values。','attribute 更中性、适用更广；impute 在普通文章里常与责任、动机相连。统计插补不等于随意编数据。',('Do not impute bad motives to her without evidence.','没有证据，不要认定她动机不良。'),('The researchers imputed the missing values and documented the method.','研究者对缺失值作了插补，并记录了所用方法。'),sources=[S('impute'),IMPDATA]),
E('imputation','英 /ˌɪmpjuˈteɪʃən/；美 /ˌɪmpjəˈteɪʃən/','归责、归因；指责；数据插补','它把“把某事记到谁头上”变成名词；统计语境则把“给空白项填入推定值”这个过程单独拿出来讨论。','可按英语 impute + -ation、受法语 imputation 影响分析，也有直接晚期拉丁 imputatio 的借入路线；不是只能选英语动词派生。',IMPUT+[['晚期拉丁 imputatio；法语 imputation','归入账下、指责'],['英语 imputation〔借入或 impute 的名词化〕','归责；后来用于统计插补']],'an imputation of dishonesty 是不诚实的指责；data imputation 是处理数据缺项的方法。两种场景都保留“给它归上一项内容”的联系，但不能把统计术语翻成指控。','an imputation of dishonesty；data imputation；an imputation method。','accusation 是直接指控；imputation 可偏向归给某人一种动机或责任。estimation 是更广的估计，不都涉及缺失值。',('She rejected the imputation that she had acted dishonestly.','她否认了对她行为不诚实的指责。'),('The report states which variables required imputation.','报告说明了哪些变量需要进行缺失值插补。'),sources=[S('imputation'),IMPDATA]),
E('amputation','英 /ˌæmpjuˈteɪʃən/；美 /ˌæmpjəˈteɪʃən/','截肢；肢体等部分的截除或截断','这条词源保留“剪去一部分”的具体动作：从树枝的剪除，发展到身体一部分被截除的名称。','拉丁 am(bi)- 周围 + putare 修剪 → amputare；其名词 amputatio 经法语 amputation 或直接拉丁借入。英语名词早于 amputate，不能画成先有英语动词再有名词。',AMP,'现代常指通过手术移除全部或部分肢体等组织，也见 traumatic amputation 指创伤导致的截断。这里说的是事件或处理名称，并不限定必须整条手臂或腿。','limb amputation；partial amputation；traumatic amputation。','excision 泛指切除组织；amputation 特别常用于肢体或突出身体部分的截除，不等于所有外科切除。',('The article discusses rehabilitation after amputation.','文章讨论了截肢后的康复。'),('The report distinguishes surgical amputation from traumatic loss of a limb.','报告区分了手术截肢与创伤造成的肢体丧失。'),sources=[S('amputation'),'https://www.cancer.gov/publications/dictionaries/cancer-terms/def/amputation',K('amputation')]),
E('amputate','英 /ˈæmpjuteɪt/；美 /ˈæmpjəteɪt/','截去；截肢','把身体的一部分截除。名字更早的拉丁背景是修剪，但今天这是清楚的医疗动作词。','可从英语 amputation 逆构，也可接拉丁 amputatus〔amputare 的分词〕形成；两种分析都不把英语 amputation 当作后出的动词派生。',B+[['拉丁 amputare → amputatus／amputatio','剪除、截去 → 分词／动作名词'],['英语 amputation 的逆构或拉丁分词来源 → amputate','截去身体的一部分']],'通常是及物动词，说明截除什么部位；被动 be amputated 很常见。词义本身不说明某位患者是否需要这一处理。','amputate a limb；a partially amputated finger；have a limb amputated。','amputee 是经历肢体截除或丧失的人；amputate 是动作，amputation 是动作名词。',('The historical account describes why the injured limb was amputated.','这份历史记载说明了受伤肢体为何被截除。'),('The surgeon explained what it meant to amputate part of the foot.','外科医生解释了截除部分足部意味着什么。'),sources=[S('amputate'),M('amputate')]),
E('amputee','英 /ˌæmpjuˈtiː/；美 /ˌæmpjəˈtiː/','截肢者；失去全部或部分肢体的人','词尾把关注点从手术移到经历这一变化的人身上。它是一项身体经历的称呼，不是对这个人能力的总评。','常分析为 amput(ate) + -ee，也可能受法语 amputé／amputée 影响；词典对英语派生与法语借入的侧重不同，不能把一种说成毫无争议。',B+[['拉丁 amputare → amputatus；法语 amputer → amputé／amputée','截除；被截除者的相关词形'],['英语 amputate 的 amput- + -ee〔有法语对应形式〕→ amputee','经历肢体截除的人']],'常见 upper-limb amputee、double amputee。具体失去哪个部位、怎样活动，需要上下文说明，不能从一个词推断所有人的状态。','an amputee athlete；support for amputees；a double amputee。','patient 指正在接受医疗照护的人；amputee 并不要求此刻仍是患者，也可说 a person with limb loss。',('The programme supports amputees returning to sport.','这个项目支持截肢者重新参与运动。'),('An amputee athlete spoke about adapting her training.','一位截肢运动员谈了自己怎样调整训练。'),sources=[M('amputee'),S('amputee'),K('amputee')]),
E('deputy','/ˈdepjəti/','副职；代理人；某些制度中的议员或警长助理','正职不在时能够顶上、平时承担部分职责的人；有些制度也用这个词称被选出代表他人的人。','来自盎格鲁法语 deputé，即古法语 deputer“委派”的过去分词名词化；远接晚期拉丁 deputare。不是英语 depute 加普通 -y 造出来的。',DEPUTY,'a deputy manager 是副经理；a deputy sheriff 是警长属下有授权的执法人员；某些国家的立法机关成员也称 deputies。具体职位必须看制度背景。','a deputy manager；the director’s deputy；a deputy sheriff。','assistant 常是协助者，不一定有代理正职的权限；deputy 更突出副职或被授权代行职责。',('The deputy chaired the meeting while the director was away.','主任外出期间，副职主持了会议。'),('She was appointed deputy manager of the branch.','她被任命为分部副经理。'),sources=[S('deputy'),M('deputy')]),
E('deputize','/ˈdepjətaɪz/','指定为代理；代行职责','给某人一个临时代行职位的身份，或者自己站到那个人的位置上，替他完成工作。','deputy 去 y + -ize，英语派生；英式也见 deputise。英语 deputy 的法语分词来源比这个动词更早。',A(DEPUTY,'英语 deputy + -ize → deputize','任命代理；作为代理行事'),'美式常及物地说 deputize someone；英式常见 deputize for someone，表示替某人履职。不同制度里的具体授权不能仅由这个词推断。','deputize someone；deputize for the manager；be deputized to act。','appoint 是广义的任命；deputize 特别涉及指定代理，或自己暂代别人。',('She will deputize for the manager during his absence.','经理不在时，她将代行经理职责。'),('The chair deputized two members to speak on the committee’s behalf.','主席指定两名成员代表委员会发言。'),sources=[S('deputy'),M('deputize')]),
]
MATHCOUNT='https://ocw.mit.edu/courses/18-100a-real-analysis-fall-2020/mit18_100af20_basic_analysis.pdf'
GRAMCOUNT='https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/nouns-countable-uncountable'
ACCTABLE=COMP+[['古法语 aconter → acontable','交代账目 → 需要交代的'],['英语 accountable','须对行为负责、接受问责的']]
DISCOUNT=COMP+[['中世纪拉丁 dis- + computare → discomputare／discomputus','从账上扣去；扣除'],['法语 desconter〔动词〕／descompte〔名词〕→ 英语 discount','扣减、打折；折扣；后来引申不重视']]
RECOUNT=COMP+[['古法语 conter → reconter；盎格鲁法语／古北法语形式','数、叙说 → 讲述'],['英语 recount〔叙述〕；另由 re- + count 形成重数义','讲述经历；重新数一遍']]
W += [
E('count','/kaʊnt/','数；算入；重要；计数、总数；另源：伯爵','用手指逐个点过去：一、二、三；后来也可以把一件事“算作重要”，所以 Every minute counts 是每一分钟都重要。','计数线来自拉丁 computare，经古法语 conter 动词与 conte 名词分别进入英语。伯爵线另经法语 conte／counte 接拉丁 comes“随从、同伴”，不是因为贵族会算账。',COUNT+[['另源并行：拉丁 comes／comitem → 法语 conte／counte','随从、官员 → 伯爵头衔'],['英语 count〔爵位义〕','伯爵；与计数线分开']],'count someone in 是把某人算进去；count on someone 是依靠；名词 a count 可指一次点数或所得数量。伯爵的 count 只是同形，不能拿来解释本词根。','count the votes；count on someone；count as；a word count。','compute 可以复杂求值；count 最核心是一项项数。count“伯爵”与 counter“反对”各有另源，不靠拼写强拉一族。',('Please count the chairs before the guests arrive.','客人到达前请数一下椅子。'),('You can count on me to finish the work.','你可以相信我会把工作完成。'),('Every small improvement counts.','每一点小进步都很重要。'),('The count welcomed the visitors to his estate.','伯爵在庄园里迎接了来访者。'),sources=[S('count'),M('count')]),
E('counting','/ˈkaʊntɪŋ/','计数；正在数；把……算在内','重点是逐项登记的过程：有没有漏数、重复算，或者把某一项包含进来。','count + -ing；计数动词沿古法语 conter 接拉丁 computare。',A(COUNT,'英语 count + -ing → counting','计数活动；正在数；将某项算入'),'not counting the driver 表示不把司机算在人数里；and counting 表示数值仍在增加；counting on... 则承接“指望”的短语义。','vote counting；not counting...；and counting；counting on someone。','counting the days 可以是数日子；counting on someone 是指望某人，不是数这个人。',('Counting the boxes twice helped us find the missing one.','把箱子数两遍，帮助我们找出了少掉的那一箱。'),('There were six people in the car, not counting the driver.','车里有六个人，司机不算在内。'),sources=[S('counting'),K('counting')]),
E('counted','/ˈkaʊntɪd/','数过了；被计入；被认为属于','一个人可能到场了，却没被名单算进去；counted 关注是否已经计数、计入或归入某类。','count + -ed；/t/ 后的 -ed 读 /ɪd/。主要沿计数动词发展，不涉及伯爵头衔。',A(COUNT,'英语 count + -ed → counted','已经计数、计入或认作'),'be counted among the best 是被列入最优秀的一群；counted on someone 是过去指望某人。词义随 count 的搭配走，不止“数过”。','counted twice；counted as；counted among；counted on someone。','counted 是实际计入；countable 是能计数，或语法、数学中的可数性质。',('One box was counted twice by mistake.','有一箱被误数了两次。'),('She is counted among the town’s most respected teachers.','她被列为镇上最受尊敬的教师之一。'),sources=[K('counted'),S('count')]),
E('countable','/ˈkaʊntəbəl/','可数的；可计数的','普通意思是能一项项数。语法里，把名词看成一个个独立单位；数学里，则问能不能给集合中的元素排上不重不漏的编号。','count + -able，英语形容词派生，后来分别用于语法和集合论。',A(COUNT,'英语 count + -able → countable','可计数的；语法和数学中的可数'),'a book、two books 中 book 是可数名词。数学常把有限集合与可列无限集合都叫 countable；例如所有整数虽无限，仍能按 0、1、-1、2、-2…列出。这里“可列”并不自动要求存在高效算法。','a countable noun；a countable set；countably infinite。','日常数不完不等于数学不可数；语法上可数也取决于词的具体义项，不是现实物体大小。',('“Suggestion” is a countable noun in this sentence.','这个句子中的 suggestion 是可数名词。'),('The set of integers is infinite but countable.','整数集是无限的，但它可数。'),sources=[K('countable'),GRAMCOUNT,MATHCOUNT]),
E('uncountable','/ʌnˈkaʊntəbəl/','不可数的；多得数不清的','语法里不能直接说“一个 advice、两个 advices”；数学里则是再怎么安排编号，也无法把全部元素一一排进自然数序列。','un- 不 + countable 可数的，英语否定派生。',A(A(COUNT,'英语 countable','可数的'),'英语 un- + countable → uncountable','不可数的'),'语法中 advice 通常不可数，要说 a piece of advice。数学中实数集合不可数，这是严格的大小性质，不能把“我没时间数”的日常困难当作证明。日常描写也有“无数”的夸张义。','an uncountable noun；an uncountable set；uncountable numbers of...。','countless 日常说极多；数学 uncountable 是专门概念。很多无限集合仍然 countable。',('“Information” is normally uncountable in English.','information 在英语中通常是不可数名词。'),('The real numbers form an uncountable set.','实数组成一个不可数集合。'),sources=[K('uncountable'),GRAMCOUNT,MATHCOUNT]),
E('countless','/ˈkaʊntləs/','无数的；多得数不清的','不是宣布做完了一项集合论证明，而是在强调“太多了，多到不想逐个报数”。','count + -less，没有可报清的数目，英语形容词派生。',A(COUNT,'英语 count + -less → countless','数量非常多、难以数清的'),'常修饰复数名词，如 countless times、countless people。多为修辞上的极多，现实数量可以完全有限。','countless times；countless examples；countless hours。','uncountable 在数学中是严格术语；countless 在普通文章中通常是强调数量，不是数学分类。',('I have checked the address countless times.','这个地址我已经核对过无数次了。'),('The archive contains countless stories of ordinary life.','档案中保存着数不清的普通生活故事。'),sources=[S('countless'),K('countless')]),
E('counter','英 /ˈkaʊntə/；美 /ˈkaʊntər/','柜台；计数器、筹码；另源：反驳、反制；相反的','柜台原来是做账、数钱的台面；计数器负责把数量累计起来。反驳别人时的 counter 则走“对着干”的另一条词源线。','柜台经古法语 contouer／comptoir 接中世纪拉丁 computatorium“算账处”；计数者等经法语 countour 接 computator 等形式。现代 count + -er 也可造计数者、计数器。反对义接法语 contre、拉丁 contra，动词也有 encounter 缩短来源。',COMP+[['拉丁 computator／中世纪拉丁 computatorium → 法语 countour、contouer／comptoir','计数者；算账处、台面'],['英语 counter〔计数线〕','计数器、筹码、柜台'],['另源并行：拉丁 contra → 法语 contre／英语 encounter 等 → counter','对着、反对 → 反驳、反制']],'at the counter 是在柜台；a step counter 是计步器；counter an argument 是反驳论点。run counter to... 是与……相反。读到反对义时，不要硬想象数数。','a kitchen counter；a step counter；counter a claim；run counter to。','counteract 的 counter- 是反对线；computer 与柜台的 counter 接计算线。相同拼写不意味着一个故事解释全部。',('She left the keys on the kitchen counter.','她把钥匙放在厨房台面上。'),('The counter records each visitor who passes the gate.','计数器记录每个经过入口的访客。'),('He countered the criticism with detailed evidence.','他用详细证据反驳了批评。'),sources=[S('counter'),K('counter')]),
E('account','/əˈkaʊnt/','账目、账户；叙述；说明；考虑；占某比例','先把钱一笔笔记清，再引申成把事情一件件交代清楚；账户则是替某个人或业务保存记录的地方。','名词经古法语 acont〔a + cont〕接拉丁 computus；动词经古法语 aconter〔a + conter〕。两支远接 computare，但不是英语先有 account 动词才造出所有名词义。',ACC,'a bank account 是银行账户，a user account 是用户账户，an account of the event 是事件的叙述。account for 可以解释原因，也可以说某部分占总数多少；take into account 则是把某因素纳入考虑。','open an account；give an account of；account for；take into account。','account 不等于只有“账户”；report 也能叙述，account 常突出某人给出的版本或交代。',('Please create an account before saving your settings.','保存设置前，请先创建账户。'),('She gave a clear account of what happened.','她清楚地叙述了事情经过。'),('Transport accounts for half of the total cost.','交通费用占总成本的一半。'),('The estimate takes seasonal changes into account.','估算把季节变化考虑在内。'),sources=[S('account'),M('account')]),
E('accountant','/əˈkaʊntənt/','会计；会计师','不只是把数字加起来的人，还要整理、检查和解释一笔笔财务记录，让账目说得清。','来自古法语 acontant／相关中古法语形式，是 aconter“算账、交代”的现在分词；现代可以看成 account + -ant，但职业名并非只在英语中临时拼成。',COMP+[['古法语 aconter → 现在分词 acontant','算账、交代账目 → 做这件事的人'],['中古英语 → accountant','从事会计工作的人']],'通常指处理财务记录的专业人员。是否具有某种执业资格，要看 certified、chartered 等具体称谓和制度，单独 accountant 不包办所有资格判断。','an accountant for a company；a chartered accountant；consult an accountant。','bookkeeper 常更侧重日常记账；accountant 通常可涉及更广的整理、分析与报告工作。',('The accountant checked the figures before the report was issued.','报告发布前，会计核对了数字。'),('She works as an accountant for a small theatre.','她在一家小剧院做会计。'),sources=[S('accountant'),K('accountant')]),
E('accounting','/əˈkaʊntɪŋ/','会计；核算；说明、交代','把每笔收入支出放到合适位置，再汇成能看懂的财务记录；这整套工作就是 accounting。','account 动词 + -ing，英语动作名词，早有计算义，后发展为财务管理与会计领域的称呼。',A(ACCV,'英语 account + -ing → accounting','核算、会计；交代说明'),'accounting department 是会计部门；an accounting of expenses 是开支的完整交代。There is no accounting for tastes 说人的喜好难以解释，不是在抱怨没人做账。','financial accounting；an accounting system；an accounting of expenses。','accountant 是人；accounting 是活动、学科或修饰语。accounts 常指账目，不等于 accounting 的所有用法。',('She studies accounting at college.','她在大学学习会计。'),('The treasurer provided a full accounting of the expenses.','财务负责人完整交代了各项开支。'),sources=[S('accounting'),K('accounting')]),
E('accountable','/əˈkaʊntəbəl/','须负责的；应接受问责的','你做了决定，就要能向相关的人说明理由、交代结果，而不是做完就没人能追问。','接古法语 acontable；也可按 account + -able 分析，核心是“能被要求交代账目、行为”。',ACCTABLE,'be accountable to someone 是向谁负责；be accountable for something 是对什么事负责。这个词说责任关系，不等于已经认定犯错。','accountable to the board；accountable for decisions；hold someone accountable。','responsible 可以只说负责做事；accountable 更突出需要说明、接受监督及承担相应责任。',('The manager is accountable to the board.','经理向董事会负责。'),('Each team is accountable for the accuracy of its own figures.','每个团队都要对自己数字的准确性负责。'),sources=[S('accountable'),K('accountable')]),
E('accountability','/əˌkaʊntəˈbɪləti/','问责；责任明确且可追究的状态','不是墙上写一句“大家负责”，而是清楚知道谁做决定、向谁说明、出了问题由谁交代。','accountable 的 -able 转为 -ability，英语抽象名词。',A(ACCTABLE,'英语 accountable → accountability','需要解释并承担责任这一性质或制度'),'常与 transparency 并用：透明让人看见发生什么，问责让相关的人必须作出交代。问责不必只有惩罚，也包括报告、说明和纠正。','public accountability；clear lines of accountability；strengthen accountability。','responsibility 可指职责；accountability 特别强调职责能被核查、向相应主体交代。',('The new process creates clearer lines of accountability.','新流程让责任归属和问责关系更加清楚。'),('Publishing the results improved transparency and accountability.','公布结果提高了透明度，也便于追究责任。'),sources=[S('accountability'),M('accountability')]),
E('unaccountable','/ˌʌnəˈkaʊntəbəl/','无法解释的；不向任何人负责的','一条线是“这事交代不出原因”，另一条是“这个人不必向谁交代行为”。两种意思都围绕 account 的说明、交代。','un- 不 + accountable；英语派生，同时否定“能解释”和“须接受问责”两种意义。',A(ACCTABLE,'英语 un- + accountable → unaccountable','无法交代原因；不受问责'),'an unaccountable delay 是莫名延误；an unaccountable authority 是不受有效问责的权力机构。看它修饰事件还是掌权者，就较容易分清。','an unaccountable error；an unaccountable feeling；unaccountable power。','inexplicable 对应无法解释义；unaccountable officials 对应无需向人负责义，两者不能总互换。',('An unaccountable error changed the order of the pages.','一个无法解释的错误打乱了页序。'),('The report criticised the concentration of unaccountable power.','报告批评了不受问责的权力过于集中。'),sources=[S('unaccountable'),M('unaccountable')]),
E('unaccountably','/ˌʌnəˈkaʊntəbli/','莫名其妙地；无法解释地','事情确实发生了，但在说话者看来，找不到一个说得通的原因。','unaccountable 的 -able 变 -ably，形成副词；通常承接“无法解释”的义项。',A(A(ACCTABLE,'英语 unaccountable','无法解释的；不受问责的'),'英语 unaccountable → unaccountably','以难以说明原因的方式'),'常放在 disappeared、changed、absent 等前，表达意外或困惑。它只说原因不明，不暗示一定是某种神秘力量。','unaccountably absent；unaccountably delayed；unaccountably missing。','unexpectedly 只是出乎意料；unaccountably 还强调说不出原因。',('The final paragraph was unaccountably missing from the printed copy.','印刷版莫名其妙地少了最后一段。'),('She felt unaccountably nervous before the familiar journey.','踏上熟悉的旅程前，她莫名感到紧张。'),sources=[S('unaccountable'),K('unaccountably')]),
E('discount','名词、形容词 /ˈdɪskaʊnt/；动词 /dɪsˈkaʊnt/，也读 /ˈdɪskaʊnt/','折扣；打折；不重视、排除某种可能','价格上“少算一点”是打折；判断上“别把它看得那么重”就是 discount 一个说法或可能性。','名词经法语 descompte，动词经 desconter，分别接中世纪拉丁 discomputus／discomputare；dis- 离开、减去 + computare 计算。现代 dis- + count 能提示意思，但两词性各有借入路线。',DISCOUNT,'get a discount 是获得价格优惠；discount a possibility 是认为这种可能不值得重视或不成立。财务中的折现也用 discount：把未来金额换算为某个较早时点的价值，须说明所用利率等假设。','a discount on tickets；sell at a discount；discount a possibility；discount future payments。','deduct 常直接减去金额；discount 既可降价，也可降低某信息在判断中的分量。',('Students receive a discount on admission.','学生购买门票可享折扣。'),('We should not discount the possibility of an error.','我们不应排除出错的可能。'),sources=[S('discount'),M('discount'),'https://www.transportation.gov/buildamerica/sites/buildamerica.dot.gov/files/2019-08/p3_primer_financial_assessment_1213.pdf']),
E('discounted','/dɪsˈkaʊntɪd/，也读 /ˈdɪskaʊntɪd/','打了折的；被低估、不予重视的；已折现的','同样是把原先的分量调低：商品降价，某条证据被看轻，或者未来款项被折算到当前时点。','discount + -ed；/t/ 后 -ed 读 /ɪd/，承接动词的不同义项。',A(DISCOUNT,'英语 discount + -ed → discounted','已降价、已排除或已折现的'),'discounted tickets 是优惠票；discounted evidence 是未被充分考虑或被排除的证据。discounted cash flow 是财务估值术语，不能译成现金在商店打折。','discounted tickets；a discounted price；discounted cash flows。','discounted price 是已降低的价格；low price 只说价格低，不说明是否从原价打过折。',('The shop offered discounted tickets to the evening event.','商店提供晚间活动的优惠票。'),('Her warning was discounted because nobody expected a failure.','因为没人预料会出故障，她的警告没有受到重视。'),sources=[K('discounted'),M('discounted'),'https://www.transportation.gov/buildamerica/sites/buildamerica.dot.gov/files/2019-08/p3_primer_financial_assessment_1213.pdf']),
E('recount','叙述 /rɪˈkaʊnt/；重新计数动词 /ˌriːˈkaʊnt/；重数名词 /ˈriːkaʊnt/','讲述、叙说；重新计数；一次重新计数','讲经历时，把事情按次序数说出来；查数量时，则把同一批东西再数一遍。两个意思的读音和进入英语的过程也不同。','叙述义经古北法语／盎格鲁法语 reconter 接 conter“数、说”；重数义由英语 re- 再 + count 另行形成。两支最终同接拉丁 computare，但不是英语重数义先变成古法语故事义。',RECOUNT,'recount an experience 是讲经历，首音节通常 /rɪ/；recount the votes 是重新计票，re- 常读 /riː/；a recount 是一次复核计数，重音前移。','recount a story；recount an experience；recount the votes；request a recount。','recall 是回想；recount 是说出来。重新计数义的 re- 很透明，叙述义则是较早借入的词。',('She recounted the journey in vivid detail.','她生动详细地讲述了那次旅程。'),('The organisers requested a recount of the votes.','组织者要求重新计票。'),('We recounted the boxes after noticing a mismatch.','发现数量对不上后，我们重新数了箱子。'),sources=[S('recount'),M('recount'),K('recount')]),
E('recounting','叙述 /rɪˈkaʊntɪŋ/；重新计数 /ˌriːˈkaʊntɪŋ/','讲述；叙述版本；重新计数','在回忆录里，它可能是一段把经历讲出来的文字；在仓库里，它可能是数量对不上之后的再数一次。','两条 recount 词义各接 -ing：叙述义沿法语 reconter，重数义沿英语 re- + count。',A(RECOUNT,'英语两种 recount + -ing → recounting','讲述的过程或版本；再次计数'),'a recounting of events 是对事件的一次叙述，可能带作者视角；recounting stock 是再次清点库存。读音跟相应的 recount 动词走。','a recounting of events；recounting a memory；recounting the stock。','recounting 可以是动作，也可以是叙述成品；counting 没有 re- 时，不明确表示再来一遍。',('Her recounting of the event differed from his.','她对事件的叙述与他的不同。'),('Recounting the stock revealed the earlier mistake.','重新清点库存后，先前的错误显现出来了。'),sources=[K('recounting'),S('recount')]),
]
ROOT=dict(id='C1174',meaning='计算、考虑、判断；较早还有修剪义',core='把数目算清，把事情想清：putare 在拉丁语里已经兼有计算、考虑、判断等意义，向外长出了算数、声誉、争论和归责几条线。',image='桌上几张纸分别写着数字、评价、理由和责任：compute 算数，reputation 是评价，dispute 争论理由，impute 把责任记到谁名下。',intro='这根来自拉丁 putare，英语 put“放”是另一个词。amputation 保存了较具体的“剪除”一线；count 和 account 经过法语后词形变化很大，仍与 compute 同源。把“清理、清点、想清楚”连起来有助记忆，但不把这个记忆画面当作已完整证实的古代语义演变过程。',forms='put-／putat- 可见于 compute、putative、reputation 等；putat- 接拉丁过去分词词干。拉丁 computare 经不同年代和路径借入，既有较保留原形的 compute，也有经过法语缩变的 count。现代 -able、-ability、-ly、-ize 派生须与整词法语、拉丁借入分开看。',branches=[['计算及计算机','compute, computed, computing, computer, computation, computational, computationally, computable, computability, computerize, computerized, computerization, recompute, microcomputer, minicomputer, supercomputer'],['计数与讲述','count, counted, counting, countable, uncountable, countless, counter, recount, recounting'],['账目与交代责任','account, accountant, accounting, accountable, accountability, unaccountable, unaccountably, discount, discounted'],['人们怎样评价','reputation, reputational, repute, reputed, reputedly, reputable, disreputable, disrepute, putative'],['讨论和质疑','dispute, disputed, disputable, disputation, indisputable, indisputably, undisputed'],['归因和插补','impute, imputation'],['委任代理','deputy, deputize'],['截除一部分','amputate, amputation, amputee']],contrasts='reputable 是口碑好，reputed 是据说如此；disputable 可争议，disputed 已有争议，undisputed 未受争议，indisputable 无可争辩。count 的伯爵义接 comes，counter 的反对义接 contra，均不属于计算线。computation、account 等名词各有借入历史，不能看到相似动词就自动画成现代英语派生。',practice='The accountant counted the receipts and computed the total. 会计先数票据，再按规则算总额。The company has a reputation for quality, but that particular claim is disputed. 总体口碑与某一条说法是否成立，也要分开判断。',words=[],exclude={w:'按用户后续选词要求暂缓：较罕用的书面、专门或可直接由常用词理解的扩展词；非词源误归类。' for w in ['reputably','disreputably','imputable','putatively','depute','deputation','disputatious','raconteur']})
if __name__=='__main__':
    m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(r for r in m['roots'] if r['id']==ROOT['id'])
    ROOT['words']=[w for w in r['family'] if '-' not in w and w not in ROOT['exclude']]
    expected=(set(ROOT['words'])&set(m['owned_words']))-{'supercomputer'};actual={e['word'] for e in W}
    assert expected==actual,(expected-actual,actual-expected)
    assert len(W)==len(actual) and all(len(e['examples'])>=2 and len(e['history'])>=2 for e in W)
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'roots_batch200_vid_34.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
    (OUT/'words_batch200_vid_34.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
    print('put:',len(W),'words;',sum(len(e['examples']) for e in W),'examples;',len(ROOT['words']),'references')
